/**
 * Committed Playwright baselines must be for the platform that READS them (#125).
 *
 * Playwright names snapshots by PLATFORM ONLY — `-linux`, `-darwin` — never by
 * architecture and never by runner. The gate runs on ubuntu, and
 * `.github/workflows/visual-baselines.yml` is `workflow_dispatch` on
 * ubuntu-latest by design, because baselines have to be produced on the platform
 * that will read them.
 *
 * So a committed `-darwin.png` is read by exactly one audience — a developer on
 * a Mac running the suite locally — and is regenerated by nothing. It rots by
 * construction. Measured when this check was written, the same four screens:
 *
 *     hitl-demo-idle   darwin 20128 B   linux 37266 B
 *     home-composer    darwin 36818 B   linux 56740 B
 *
 * which is not drift around the edges, it is a different rendering. #125 filed
 * it as "~99% drifted: CI will be green while every Mac dev sees red".
 *
 * WHY DELETING THEM IS THE FIX RATHER THAN REGENERATING THEM. A second platform's
 * baselines need a second platform's generator, a second adoption decision, and a
 * second thing to keep current — for an audience that is not the gate. Since #147,
 * a MISSING snapshot is an error rather than a silent request to generate, so a
 * Mac developer now gets an honest "no baseline for darwin" naming the file,
 * instead of a red that reads as a regression they did not cause.
 *
 * Exit 0 clean, 1 on any non-linux baseline, 2 on bad usage.
 */
import { readdirSync, existsSync, statSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { dirname, resolve } from "node:path";

const ALLOWED_PLATFORM = "linux";
const SNAPSHOT_SUFFIX = /-([a-z0-9]+)\.png$/;

/** Every `*-snapshots` directory under a root, recursively. */
export function snapshotDirs(root, acc = []) {
  if (!existsSync(root)) return acc;
  for (const entry of readdirSync(root)) {
    if (entry === "node_modules" || entry.startsWith(".")) continue;
    const p = join(root, entry);
    if (!statSync(p).isDirectory()) continue;
    if (entry.endsWith("-snapshots")) acc.push(p);
    else snapshotDirs(p, acc);
  }
  return acc;
}

/** Baselines whose platform suffix is not the one the gate reads. */
export function offenders(dirs) {
  const found = [];
  for (const dir of dirs) {
    for (const f of readdirSync(dir)) {
      const m = SNAPSHOT_SUFFIX.exec(f);
      if (!m) continue;
      if (m[1] !== ALLOWED_PLATFORM)
        found.push({ file: join(dir, f), platform: m[1] });
    }
  }
  return found;
}

export function main(argv) {
  const root = argv[0] ?? "e2e";
  const dirs = snapshotDirs(root);

  // VACUITY GUARD. With no snapshot directory this check has no subject, and
  // "0 offenders" would be indistinguishable from "nothing was examined" — the
  // defect this repo keeps finding. Say so and fail as bad usage, not as clean.
  if (dirs.length === 0) {
    console.error(
      `check-visual-baselines: no *-snapshots directory under "${root}". ` +
        `Nothing was examined, so this is not a pass.`
    );
    return 2;
  }

  const bad = offenders(dirs);
  console.log(
    `check-visual-baselines: ${dirs.length} snapshot dir(s), platform "${ALLOWED_PLATFORM}"`
  );
  if (bad.length === 0) {
    console.log(
      "clean — every committed baseline is for the platform CI reads."
    );
    return 0;
  }
  console.error(
    `\nFAIL: ${bad.length} baseline(s) for a platform the gate never reads:\n`
  );
  for (const b of bad) console.error(`    ${b.file}   (-${b.platform})`);
  console.error(
    `\n  Playwright names snapshots by platform only, and the gate runs on ${ALLOWED_PLATFORM}.` +
      `\n  A -${bad[0].platform} baseline is regenerated by nothing and rots by construction.` +
      `\n  Delete them. Since #147 a missing snapshot is an honest error naming the file,` +
      `\n  which beats a stale one that reads as a regression you did not cause.` +
      `\n\n  Regenerate the ${ALLOWED_PLATFORM} set with the "Visual baselines (manual)" workflow.\n`
  );
  return 1;
}

const isEntry = (() => {
  if (!process.argv[1]) return false;
  try {
    return (
      resolve(fileURLToPath(import.meta.url)) === resolve(process.argv[1]) ||
      (dirname(fileURLToPath(import.meta.url)).length > 0 &&
        fileURLToPath(import.meta.url).endsWith(
          process.argv[1].split("/").pop()
        ))
    );
  } catch {
    return false;
  }
})();
if (isEntry) process.exit(main(process.argv.slice(2)));
